<?php

namespace App\Modules\Assets\Models;

use App\Core\User\Models\User;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Str;

/**
 * M6 — Misuse Detection Event
 * 
 * Flagged anomalies indicating potential asset misuse.
 * Generated by AssetMisuseDetectionService analyzing behavior patterns.
 */
class AssetMisuseEvent extends Model
{
    protected $table = 'asset_misuse_events';

    protected $fillable = [
        'uuid',
        'asset_id',
        'custodian_user_id',
        'event_type',                // unauthorized_transfer | excessive_usage | location_anomaly | after_hours_usage | policy_violation
        'severity',                  // low | medium | high | critical
        'detected_at',
        'description',
        'evidence',                  // JSON — supporting data
        'confidence_score',          // 0-100
        'status',                    // flagged | investigating | resolved | false_positive
        'investigated_by_user_id',
        'investigated_at',
        'resolution_notes',
    ];

    protected $casts = [
        'detected_at'       => 'datetime',
        'investigated_at'   => 'datetime',
        'evidence'          => 'array',
        'confidence_score'  => 'integer',
    ];

    protected static function boot()
    {
        parent::boot();

        static::creating(function ($model) {
            if (!$model->uuid) {
                $model->uuid = (string) Str::uuid();
            }
        });
    }

    // Relationships
    public function asset(): BelongsTo
    {
        return $this->belongsTo(Assets::class, 'asset_id');
    }

    public function custodian(): BelongsTo
    {
        return $this->belongsTo(User::class, 'custodian_user_id');
    }

    public function investigatedBy(): BelongsTo
    {
        return $this->belongsTo(User::class, 'investigated_by_user_id');
    }

    // Helpers
    public function isResolved(): bool
    {
        return in_array($this->status, ['resolved', 'false_positive']);
    }

    public function isCritical(): bool
    {
        return $this->severity === 'critical';
    }

    public function isHighConfidence(): bool
    {
        return $this->confidence_score >= 75;
    }
}
